-- Wiener Schmäh jokes (100); category keybinds JokeYell
Set("NERGLISH_JOKE_1", [=[Beim Bewerbungsgespräch fragt der Chef nach meinen Stärken. „I komm mit jedem aus, solang er mi in Ruah lässt.“ Er nickt. „Teamfähig, schreib i.“]=])
Set("NERGLISH_JOKE_2", [=[Am Stephansplatz fragt mich ein Tourist nach dem Weg zum Prater. „Immer der Nase nach. Riecht’s nach Zuckerwatte, san S’ richtig. Riecht’s wieder nach Kaffee, san S’ im Kreis gangen.“]=])
Set("NERGLISH_JOKE_3", [=[Im Kaffeehaus frag ich nach einem zweiten Glas Wasser. Der Ober schaut auf meinen kleinen Braunen. „Was haben S’ vor? Wollen S’ drin schwimmen?“]=])
Set("NERGLISH_JOKE_4", [=[In der U6 kommt die Durchsage: „Bitte alle aussteigen.“ Einer bleibt sitzen. „Na endlich sagt amal wer bitte, und jetzt soll i gehn?“]=])
Set("NERGLISH_JOKE_5", [=[Am Naschmarkt frag ich den Standler, ob der Käse mild is. „Im Vergleich zu meiner Ex schon.“]=])
Set("NERGLISH_JOKE_6", [=[Bei uns im Gemeindebau hörst nach zehn jeden Tastenschlag vom Nachbarn. Gestern klopf ich an die Wand: „Was tippst denn um die Zeit?“ Kommt’s zurück: „A Beschwerde über die dünnen Wänd!“]=])
Set("NERGLISH_JOKE_7", [=[Beim Würstelstand bestell ich a Eitrige. „Haben S’ auch was Leichtes?“ Der Standler legt ma a Serviettn hin.]=])
Set("NERGLISH_JOKE_8", [=[„Wohin fahren S’?“, fragt der Taxler. „Zur Schwiegermutter. Aber lassen S’ sich Zeit.“ Er schaltet das Navi aus. „Da kenn i an Umweg.“]=])
Set("NERGLISH_JOKE_9", [=[Beim Heurigen frag ich, ob der Wein trocken is. Der Wirt schaut über mich rauf. „Der Wein schon. Sie sitzen unter der Regenrinne.“]=])
Set("NERGLISH_JOKE_10", [=[In Schönbrunn hab ich mich über den Panda gewundert. Zwei Stunden sitzt der da und schaut deppert. Dann seh ich in der Scheibe mein Spiegelbild.]=])
Set("NERGLISH_JOKE_11", [=[Mein Opa nennt die U-Bahn immer noch „die neue Verbindung“. „Opa, die is älter als i.“ – „Und? Zu dir sag i aa noch Bua.“]=])
Set("NERGLISH_JOKE_12", [=[Im Prater hab ich für die Geisterbahn gezahlt. Hätt ich gewusst, dass mich dort nur wer im Dunkeln anschreit, wär ich zum Familienessen gangen.]=])
Set("NERGLISH_JOKE_13", [=[Im Wetterbericht heißt’s: „Am Nachmittag freundlich.“ Mein Nachbar zieht die Vorhänge zu. „Schau ma, wer länger durchhält.“]=])
Set("NERGLISH_JOKE_14", [=[Im Kaffeehaus streiten zwei seit dreißig Jahren über Politik. Heut waren sie einer Meinung. Der Ober hat vorsichtshalber die Rettung gerufen.]=])
Set("NERGLISH_JOKE_15", [=[Ein Tourist fragt, ob die Wiener immer so unfreundlich sind. „Nur wenn’s voll is.“ Er schaut sich im leeren Lokal um. „In Wien“, sag ich.]=])
Set("NERGLISH_JOKE_16", [=[In der Bim biet ich einer älteren Dame meinen Platz an. Sie schaut mich an. „Bleiben S’ sitzen. Sie brauchen ihn heut dringender.“]=])
Set("NERGLISH_JOKE_17", [=[Auf der Donauinsel hat mein Hawara ein Zelt aufgestellt. Nach zehn Minuten haben drei Leut nach dem Bierpreis gefragt. Jetzt schickt er mich zum Billa.]=])
Set("NERGLISH_JOKE_18", [=[Beim Friseur sag ich: „Wie immer.“ – „Sie waren noch nie da.“ – „Na schau, dann könn ma heut beide behaupten, es g’hört so.“]=])
Set("NERGLISH_JOKE_19", [=[Am Zentralfriedhof frag ich den Gärtner nach einer Abkürzung. „Lassen S’ sich Zeit. Hier rennt Ihnen keiner davon.“]=])
Set("NERGLISH_JOKE_20", [=[Mein Nachbar regt sich auf, weil die Nachbarin so viel tratscht. Ich frag ihn, woher er das weiß. Er rückt mir einen Sessel her. „Setz di. Des dauert.“]=])
Set("NERGLISH_JOKE_21", [=[Beim Würstelstand hab ich nach einer Weinbegleitung gefragt. Jetzt steht der Herr Franz mit seinem Spritzer neben mir und fragt, ob ma noch wo hingehn.]=])
Set("NERGLISH_JOKE_22", [=[Im Kaffeehaus frag ich nach dem WLAN-Passwort. Der Ober sagt: „Steht auf der Rechnung.“ Beim Zahlen zeig ich ihm den Zettel. „Und wo?“ Er seufzt. „Alles klein. Ohne Leerzeichen.“]=])
Set("NERGLISH_JOKE_23", [=[Mein Hawara hat mir beim Übersiedeln geholfen. Auf der schwersten Kiste steht „Bücher“. Er hebt sie an. „Hättst in der Schule besser aufpasst, müsstest des ned alles aufheben.“]=])
Set("NERGLISH_JOKE_24", [=[Der Ober fragt, ob’s geschmeckt hat. „Ausgezeichnet.“ Er schaut auf meinen Teller. „Und was genau hat Ihnen die Petersilie getan?“]=])
Set("NERGLISH_JOKE_25", [=[Meinen ersten Grant hab ich vom Opa geerbt. Er lebt noch. Er wollt nur sehen, ob ich ihn ordentlich pfleg.]=])
Set("NERGLISH_JOKE_26", [=[Auf der Alm steht „Frische Milch“. Ich frag den Bauern, wie frisch. Er deutet auf die Kuh. „Die überlegt noch.“]=])
Set("NERGLISH_JOKE_27", [=[Die Oma fragt, ob ich ein Stück Gugelhupf mag. „Nur ein dünnes, bitte.“ Sie schneidet zwei dünne runter. „Schau, so dünn kriegst es sonst nirgends.“]=])
Set("NERGLISH_JOKE_28", [=[Im Wirtshaus steht „hausgemacht“ auf der Karte. Ich frag den Wirt, welches Haus. Er deutet auf die Mama in der Küche. „Fragen S’ selber, wenn S’ sich trauen.“]=])
Set("NERGLISH_JOKE_29", [=[Beim Wandern sagt der Tiroler: „Noch zehn Minuten.“ Eine halbe Stunde später frag ich wieder. „Noch zehn Minuten.“ – „Des hast vorhin aa g’sagt!“ – „Siehst, auf mi kannst di verlassen.“]=])
Set("NERGLISH_JOKE_30", [=[Ich hab der Mama gesagt, ich komm zum Essen, aber nur kurz. Sie hat mir drei Schnitzel eingepackt. „Dann verlierst beim Kauen ka Zeit.“]=])
Set("NERGLISH_JOKE_31", [=[Beim Skikurs hab ich gelernt, wie man stehen bleibt. Die zwei Techniken heißen Schneepflug und Zaun.]=])
Set("NERGLISH_JOKE_32", [=[Im Dorfgasthaus sagt der Wirt: „Setz di, i bring da des Übliche.“ Ich bin zum ersten Mal dort. Er stellt mir ein Bier hin, setzt sich dazu und fragt: „So. Wem g’hörst du?“]=])
Set("NERGLISH_JOKE_33", [=[Der Wetterbericht sagt Föhn an. Mein Onkel greift sich aufs Knie. „Hab i gestern scho g’spürt.“ Sagt die Tant: „Dir tut seit 1998 jeden Tag des Knie weh. Irgendwann wird halt amal Föhn sein.“]=])
Set("NERGLISH_JOKE_34", [=[Ich frag den Wirt, ob ich das Schnitzel auch als kleine Portion krieg. „Freilich.“ Er holt an größeren Teller.]=])
Set("NERGLISH_JOKE_35", [=[Am Bauernmarkt bestell ich sechs Eier. Die Bäuerin gibt mir sieben. „Eins für den Heimweg.“ Dann schaut sie auf mein Radl und legt noch eins dazu.]=])
Set("NERGLISH_JOKE_36", [=[Am Gemeindeamt zieh ich eine Nummer. Hinterm Schalter ruft’s: „Mani, komm her!“ Den Zettel hab ich eingerahmt. Mein erstes Papier vom Amt, für das ich nix mitbringen hab müssen.]=])
Set("NERGLISH_JOKE_37", [=[Mein Nachbar misst den Schnee am Gartenzwerg. Heut schaut nur noch die Zipfelmütze raus. Er startet die Schneefräse. „Jetzt oder im Frühjahr mit’m Rasenmäher.“]=])
Set("NERGLISH_JOKE_38", [=[In Salzburg hab ich eine Mozartkugel gekauft. Bis zum Ausgang hab ich vier Meinungen gehört, ob’s die richtige war. Geschmeckt hat sie mir heimlich.]=])
Set("NERGLISH_JOKE_39", [=[In Graz frag ich einen, wie spät’s is. Er zeigt auf den Uhrturm. „Da musst nur die Stiegen rauf.“ – „Bis i oben bin, stimmt’s ja nimmer.“]=])
Set("NERGLISH_JOKE_40", [=[Mein Vater sagt beim Einparken: „Des geht si aus.“ Dann schrammt’s. Die Mama schaut vom Handy auf. „Der Platz oder der Selbstbehalt?“]=])
Set("NERGLISH_JOKE_41", [=[Mein Onkel geht Schwammerl suchen. Drei Stunden später kommt er mit zwei Semmeln und einer Wurst heim. „Der Wald hat heut nix g’habt. Der Billa schon.“]=])
Set("NERGLISH_JOKE_42", [=[Bei uns gibt’s am Sonntag um zwölf Mittagessen. Wer um fünf nach zwölf kommt, kriegt auch was Warmes. Eine Standpauke.]=])
Set("NERGLISH_JOKE_43", [=[Im Burgenland wollt ich nur ein Achterl kosten. Der Winzer stellt die Flasche auf den Tisch. „I lass Sie mit der Entscheidung kurz allein.“]=])
Set("NERGLISH_JOKE_44", [=[In Vorarlberg hab ich beim Bäcker nach dem Weg gefragt. Nach seiner Antwort hab ich freundlich genickt und zwei Brote gekauft. Beim zweiten Besuch hab ich gleich nach Brot gefragt. Jetzt weiß ich, wo der Bahnhof is.]=])
Set("NERGLISH_JOKE_45", [=[In Kärnten frag ich am Steg, wie kalt der See is. Mein Cousin stellt sein Bier ab. „Willst a Zahl, oder soll i da helfen?“]=])
Set("NERGLISH_JOKE_46", [=[Beim Familienessen sag ich zur Oma: „I bin satt.“ Sie nimmt mir die Gabel weg und gibt mir einen Löffel. „Fürn Pudding brauchst eh ka Gabel.“]=])
Set("NERGLISH_JOKE_47", [=[Am Kirtag hab ich beim Dosenwerfen dreimal nix troffen. Beim vierten Versuch beugt sich der Standler zu mir. „Den Ball derfst schon loslassen.“]=])
Set("NERGLISH_JOKE_48", [=[Die Nachbarin wollt nur schnell die Gartentür aufmachen. Zwanzig Minuten später steh ich immer noch draußen, weiß aber, warum ihr Schwager wieder einen Kombi braucht.]=])
Set("NERGLISH_JOKE_49", [=[Am Berg steht „Noch 15 Minuten“. Nach einer halben Stunde kommt wieder so a Tafel. Diesmal steht a Bank daneben. Wenigstens kann i mich beim Auslachen hinsetzen.]=])
Set("NERGLISH_JOKE_50", [=[Die Oma verrät ihr Knödelrezept gern. „A bissl Mehl, a Gspür fürs Wasser.“ Bei uns in der Familie gelingen die immer. Nach drei Minuten sagt sie „Geh auf d’Seit“ und macht’s selber.]=])
Set("NERGLISH_JOKE_51", [=[Der Greifenmeister am Stephansplatz ruft: „Wegen Bauarbeiten endet dieser Flug in Meidling.“ Der Greif dreht sich um. „Und wie kumm i jetzt ham?“]=])
Set("NERGLISH_JOKE_52", [=[Vorm Raid in Sturmwind geht der Jäger noch schnell zum Würstelstand. Beim ersten Boss ruft der Tank: „Wo is dein Pet?“ – „Beim Standler. Irgendwer muss ja auf die Zweite aufpassen.“]=])
Set("NERGLISH_JOKE_53", [=[In Eisenschmiede frag ich den Händler nach einer Haube. „Für den Kopf?“ – „Na, fürs Schnitzel.“]=])
Set("NERGLISH_JOKE_54", [=[Beim Heurigen in Goldhain gibt’s blaue Manatränke. Nach dem dritten zauber ich zur Probe einen Feuerball. Kommt nur ein Funken. Der Wirt nickt. „Sie haben ja auch an G’spritzten bestellt.“]=])
Set("NERGLISH_JOKE_55", [=[Ein Wiener Magier macht Portale nur bis zur Stadtgrenze. „Ab da brauch i an zweiten Fahrschein.“]=])
Set("NERGLISH_JOKE_56", [=[Wie beim Heurigen die Rechnung kommt, macht sich der Schurke unsichtbar. Der Wirt schenkt allen nach, nur sein Glas bleibt leer. „Heast, und i?“ – „Ah, da san S’ ja.“]=])
Set("NERGLISH_JOKE_57", [=[Bei der Skihütte im Schwarzfels frag ich: „Geht der Lift bis ganz rauf zum Endboss?“ Der Liftwart nickt. „Kaufen S’ ruhig nur die Bergfahrt. Bis jetzt is jeder am Friedhof unten wieder rauskommen.“]=])
Set("NERGLISH_JOKE_58", [=[Der Questgeber in Favoriten will zehn Eberhauer. Ich bring ihm zwölf. „Für die zwei zu viel musst a eigenes Formular ausfüllen.“]=])
Set("NERGLISH_JOKE_59", [=[Mein Gnomenkrieger will aufs Wiener Riesenrad. Bei der Kassa heißt’s: „Für die Gondel bist zu klein.“ Er stellt sich auf sein Schild. „Und jetzt?“ – „Jetzt brauchst für den Schild a Karte.“]=])
Set("NERGLISH_JOKE_60", [=[Beim Duell im Gemeindebau zieht der Paladin die Bubble. Vom Balkon ruft’s: „Bua, die Hausordnung gilt in der Bubble aa!“]=])
Set("NERGLISH_JOKE_61", [=[Der Jäger nennt sein Pet „Schatzi“. Am Würstelstand ruft er: „Schatzi, aus!“ Der Hund gehorcht. Zwei Ehemänner legen die Wurst zurück.]=])
Set("NERGLISH_JOKE_62", [=[Im Schlingendorntal erzählt ein Kärntner von seinem letzten Fang. Bei jeder Runde wird der Fisch größer. Nach der dritten unterbricht ihn unser Tank: „Bevorst weitererzählst: Reichen zwei Heiler?“]=])
Set("NERGLISH_JOKE_63", [=[Vorm Kaffeehaus verwandelt sich der Druide in eine Katze. Sofort bringt ihm der Ober ein Schälchen Wasser. Ich wart seit einer Stunde auf meins. Der Druide schiebt’s mir mit der Pfote rüber.]=])
Set("NERGLISH_JOKE_64", [=[Ein Zwerg bestellt ein kleines Bier. Der Wirt mustert ihn. „Passt.“ Der Zwerg deutet auf den Tauren hinter sich. „Des is für ihn. I vertrag a großes.“]=])
Set("NERGLISH_JOKE_65", [=[Unser Krieger hat Spott von seiner Wiener Oma gelernt. Der Boss schaut weg, der Krieger ruft „So gehst ma aus’m Haus?“ und schon dreht er sich wieder um.]=])
Set("NERGLISH_JOKE_66", [=[Beim Flug über die Alpen fragt der Greifenmeister, wer schon einmal in Innsbruck gelandet is. Der Greif hebt eine Kralle. „Gott sei Dank“, sagt der Greifenmeister.]=])
Set("NERGLISH_JOKE_67", [=[In Orgrimmar frag ich die Wache nach dem Auktionshaus. „Beim Tor links.“ – „Von mir aus oder von Ihnen aus?“ Sie seufzt. „Wissen S’ was? I geh eh grad.“]=])
Set("NERGLISH_JOKE_68", [=[Mein Untoter bestellt ein Naturschnitzel. Der Wirt fragt: „Seit wann isst du deins ohne Panier?“ – „Seit i beim letzten Mal nach jedem Bissen die Brösel aus den Rippen schütteln hab müssen.“]=])
Set("NERGLISH_JOKE_69", [=[Ein Schamane hat in Wien vier Totems aufgestellt. Jetzt hängen drei Fahrräder dran und eines ist für einen Gastgarten reserviert.]=])
Set("NERGLISH_JOKE_70", [=[Der Paladin segnet das ganze Wirtshaus. Aus der Küche ruft der Wirt: „Wennst eh dabei bist, leg dem Geschirrspüler die Händ auf. Der klingt seit Mittag so komisch.“]=])
Set("NERGLISH_JOKE_71", [=[Auf der Alm bufft der Priester die ganze Gruppe mit Stärke. Der Senner nimmt ihn zur Seite. „Mir gibst des aa. Der Kuh bitte nimmer. Die Stalltür war neu.“]=])
Set("NERGLISH_JOKE_72", [=[Ein Taure kommt zum Opernball. An der Garderobe gibt er die Axt ab, dann den Helm. Die Dame schaut auf die Hörner. „Die g’hörn zu Ihnen, oder brauch ma noch a Nummer?“]=])
Set("NERGLISH_JOKE_73", [=[Der Hexenmeister bringt seinen Dämon zum Familienessen mit. Die Oma schenkt ihm nach, obwohl der Sessel schon raucht. „Lasst’s den Buben. Dem is halt warm.“]=])
Set("NERGLISH_JOKE_74", [=[Der Zeppelin hat Verspätung. Der Goblin organisiert Ersatzverkehr. Jetzt sitzen wir zu viert auf einem Greifen. „Wer beim Schwedenplatz runterwill, zupft links an der Feder.“]=])
Set("NERGLISH_JOKE_75", [=[Am Würstelstand sagt der Murloc: „Mrrgrl.“ Der Standler stellt ihm ein Bier hin. „Woher hast gwusst, was er will?“ – „Um die Uhrzeit reden’s alle so.“]=])
Set("NERGLISH_JOKE_76", [=[Der Raidlead sagt: „Beim nächsten Pull bleiben alle ruhig.“ Der Boss stürmt los. Unser Tank seufzt. „Der war bei der Besprechung wieder ned dabei.“]=])
Set("NERGLISH_JOKE_77", [=[Vor dem Pull zaubert der Magier einen Tisch. Der Tank fragt: „Gibt’s auch was Warmes?“ Hinter ihm holt der Drache tief Luft. „Gleich.“]=])
Set("NERGLISH_JOKE_78", [=[„Wer hat den Boss gepullt?“ Der Jäger sagt: „Mein Pet.“ Das Pet schaut den Jäger an. So deutlich hat ein Wolf noch nie „Oida“ gesagt.]=])
Set("NERGLISH_JOKE_79", [=[Beim ersten „letzten Versuch“ sag ich der Gilde gute Nacht. Beim zweiten meiner Frau. Beim dritten geht hinter mir das Licht aus.]=])
Set("NERGLISH_JOKE_80", [=[Unser Tank kennt den Kampf auswendig. Bei der ersten Mechanik sagt er „Hoppala“, bei der zweiten „Na geh“. Wenn er ganz still wird, können die Heiler schon freilassen.]=])
Set("NERGLISH_JOKE_81", [=[Der Heiler ruft: „Line of Sight!“ Unser Krieger schaut hinter der Säule hervor. „Ja servas.“ Dann geht er wieder in Deckung.]=])
Set("NERGLISH_JOKE_82", [=[Der Raidlead sagt: „Wir brauchen mehr Schaden.“ Unser Hexer nimmt sein Handy raus. „Soll i die Mama dazuholen? Die macht euch alle fertig.“]=])
Set("NERGLISH_JOKE_83", [=[Beim Würfeln um einen Edelstein schreibt einer: „Brauch i dringend!“ Fünf Minuten später seh ich den Stein im Auktionshaus. „Was war denn so dringend?“ – „Die Reparaturrechnung.“]=])
Set("NERGLISH_JOKE_84", [=[Der Boss hat drei Phasen. In Phase eins stirbt der Jäger. In Phase zwei erklärt er, warum. In Phase drei erzählt er’s dem Ersatzjäger.]=])
Set("NERGLISH_JOKE_85", [=[Unser Schurke knackt seit zwanzig Minuten dieselbe Tür. Ich halt ihm den Schlüssel hin. „Jetzt nimmer“, sagt er. „Jetzt is persönlich.“]=])
Set("NERGLISH_JOKE_86", [=[Der Krieger hat beim Taktikvideo vorgespult. Jetzt kennt er die Begrüßung, die Werbung und die Stelle, wo alle jubeln. Beim Pull fragt er: „Wie lang noch bis zum Jubeln?“]=])
Set("NERGLISH_JOKE_87", [=[Unser Druide wechselt im Raid dauernd die Gestalt. Nach dem Wipe fragt der Heiler: „Was warst du zum Schluss? Da liegt a Katz, und i will ned die falsche mitnehmen.“]=])
Set("NERGLISH_JOKE_88", [=[Im Auktionshaus unterbiet ich denselben Kerl seit einer Stunde um einen Kupfer. Jetzt flüstert er: „I geh kurz essen. Lass ma den Preis derweil so?“]=])
Set("NERGLISH_JOKE_89", [=[Beim Bereitschaftscheck klicken 39 auf Ja. Einer knuspert seit zehn Minuten ins Mikro. „Franz, bist so weit?“ – „Moment.“ Dann hör ma, wie er das Sackerl umdreht und sich den Rest in den Mund schüttet.]=])
Set("NERGLISH_JOKE_90", [=[Wir haben dem Boss gestern ein Prozent gelassen. „Des holen wir uns morgen“, sagt der Raidlead. Genau so redet die Oma, wenn noch a Restl Erdäpfelsalat da is.]=])
Set("NERGLISH_JOKE_91", [=[Nach dem Wipe sagt der Priester: „Wer als Erster stirbt, zahlt allen die Reparatur.“ Auf einmal steht der Jäger auf, teilt Gruppen ein und erklärt uns die Mechanik.]=])
Set("NERGLISH_JOKE_92", [=[Der Boss liegt. Unser Raidlead gibt noch zwei Minuten Anweisungen. Jetzt weiß der Boss wenigstens, wo er beim Sterben hätt stehen sollen.]=])
Set("NERGLISH_JOKE_93", [=[Nach dem Wipe fragt der Raidlead: „Wer kann wiederbeleben?“ Der Schamane sagt: „I.“ – „Super, dann fang an.“ – „Mich hab i g’meint. Euch hab i eh gern g’habt.“]=])
Set("NERGLISH_JOKE_94", [=[Beim ersten Pull hatten wir keinen Plan. Beim zweiten hatten wir einen. Nach dem dritten waren wir uns einig: Der erste war besser.]=])
Set("NERGLISH_JOKE_95", [=[Unser Tank bleibt sogar im Raid höflich. „Könntest vielleicht aus dem Feuer raus?“ – „Geht grad ned.“ Drei Sekunden später fragt der Tank: „Soll i dir die Bitte beim nächsten Pull a bissl früher sagen?“]=])
Set("NERGLISH_JOKE_96", [=[Der Raidlead wollt, dass alle pünktlich sind. Der Jäger war zehn Minuten vorher da. Sein Pet war zwanzig Minuten vorher beim Boss.]=])
Set("NERGLISH_JOKE_97", [=[Im Gildenchat fragt wer, ob ihm jemand beim Leveln hilft. Die Antwort kommt sofort. „Bin fix dabei, wennst 60 bist.“]=])
Set("NERGLISH_JOKE_98", [=[Der Magier stellt ein Portal nach Donnerfels. Der Tank geht als Erster durch. Jetzt tankt er 38 Beschwerden und kriegt ein Dankeschön von einem Tauren, der eh heimwollt.]=])
Set("NERGLISH_JOKE_99", [=[Unser Gruppenleiter hat einen kurzen Lauf versprochen. Er hat den Weg vom Friedhof zum Eingang gemeint. Den schaffen wir mittlerweile in Rekordzeit.]=])
Set("NERGLISH_JOKE_100", [=[Der Endboss brüllt: „Ihr seid töricht, euch mir entgegenzustellen!“ Unser Tank sagt: „Eh. Aber wir san vierzig Leut und ham endlich an Termin g’funden.“]=])

-- Azeroth Schmäh jokes (100); AzerothJokeYell Auto pack
Set("NERGLISH_AZEROTH_1", [=[Unser Tank wird für die zweite Phase abgelöst. Er bleibt neben dem Boss stehen. „I bin in Pause. Zuschauen, wie’s wer anderer falsch macht, darf i.“]=])
Set("NERGLISH_AZEROTH_2", [=[Der Raidlead fragt, warum keiner unterbrochen hat. Der Schurke sagt „Der Boss hat so lang an dem Satz g’arbeitet. I wollt wissen, wie er ausgeht.“]=])
Set("NERGLISH_AZEROTH_3", [=[Beim Aufteilen in zwei Gruppen sagt der Raidlead „Wer links und rechts verwechselt, geht mit mir.“ Auf einmal steht der halbe Raid bei ihm. „Na wenigstens san ma ehrlich.“]=])
Set("NERGLISH_AZEROTH_4", [=[Der Boss lässt eine Hose fallen. Unser Tank gewinnt sie. „Endlich. Jetzt kann i meiner Frau erklären, warum i seit acht Wochen Donnerstagabend so lang weg bin.“]=])
Set("NERGLISH_AZEROTH_5", [=[„Die roten Kreise san gefährlich“, sagt der Raidlead. Unser Jäger fragt „Alle?“ Seitdem heißt er intern „der Rotkreuztester“.]=])
Set("NERGLISH_AZEROTH_6", [=[Die Heilung war heut so gut, dass unser Krieger erst nach dem Pull erfahren hat, dass er zweimal hätt sterben sollen. Er hat sich beim Heiler für beide Überstunden bedankt.]=])
Set("NERGLISH_AZEROTH_7", [=[Der Raidlead stellt ein Totenkopfsymbol auf und sagt, dort sollen alle sammeln. Unser Zwerg stellt sich daneben. „Unter so an Schild stell i mi erst, wenn’s Konto abbezahlt is.“]=])
Set("NERGLISH_AZEROTH_8", [=[Der Heiler sagt „I hab alles in dich reingesteckt.“ Der Tank sagt „Und trotzdem bin i umg’fallen.“ Der Heiler seufzt. „Ja, an die Rede erinner i mi von deiner Mutter.“]=])
Set("NERGLISH_AZEROTH_9", [=[Unser Magier hat Spiegelbilder beschworen. Drei davon sind der Mechanik ausgewichen. Jetzt muss der Raidlead entscheiden, wen er für nächste Woche einlädt.]=])
Set("NERGLISH_AZEROTH_10", [=[Der Boss brüllt „Ich kenne eure Schwächen!“ Unser Tank sagt „Dann sag’s dem Heiler. Der sucht meine seit drei Pulls.“]=])
Set("NERGLISH_AZEROTH_11", [=[Die Gilde hat ein Gruppenfoto nach dem Bosskill gemacht. Nach fünf Minuten waren alle richtig aufgestellt. „Schauts“, sagt der Raidlead. „Bei drei hätt ma den Boss auch so g’habt.“]=])
Set("NERGLISH_AZEROTH_12", [=[Bei uns im Raid heißt „Bitte auf die Ansage hören“, dass gleich vier Leute gleichzeitig erklären, was für eine Ansage gemeint war.]=])
Set("NERGLISH_AZEROTH_13", [=[Wer den ersten Fehler macht, muss beim nächsten Pull runterzählen. Unser Jäger kann mittlerweile von zehn runter in drei Sprachen.]=])
Set("NERGLISH_AZEROTH_14", [=[Der Tank fragt, warum ihm der zweite Tank beim Wechsel den Boss zu spät abnimmt. „I hab g’wartet, bis du mit ihm fertig g’redet hast.“]=])
Set("NERGLISH_AZEROTH_15", [=[Nach dem Wipe fragt wer „War das heilbar?“ Unser Priester sagt „Theoretisch ja. Theoretisch hätt i heut aber auch frei g’habt.“]=])
Set("NERGLISH_AZEROTH_16", [=[Unser Hexer hat vorm Raid Gesundheitssteine verteilt. Nach dem Wipe fragt er, warum alle ihren noch haben. Der Zwerg sagt „Meiner war für an Notfall.“]=])
Set("NERGLISH_AZEROTH_17", [=[Der Raidlead sagt „Der Boss is bei dreißig Prozent.“ Unser Zwerg greift zum Getränk. „Meins auch. Soll i gleichzeitig drücken?“]=])
Set("NERGLISH_AZEROTH_18", [=[Die Reparatur nach dem Raid hat mich acht Gold gekostet. Der Schmied hat einmal auf meinen Brustpanzer geklopft. „Des war die Anfahrt. Soll i anfangen?“]=])
Set("NERGLISH_AZEROTH_19", [=[Der Boss war immun. Unser Krieger hat zwölf Sekunden weiter draufgehauen. „Des hab i scho g’merkt. I wollt, dass er’s auch merkt.“]=])
Set("NERGLISH_AZEROTH_20", [=[Nach dem Kill sagt der Raidlead „Merkt’s euch, wie das grad gangen is.“ Unser Tank sagt „I hab vor lauter Überraschung wegschaut.“]=])
Set("NERGLISH_AZEROTH_21", [=[Vier Leute stehen vorm Dungeon. Der Fünfte schreibt „Bin eh schon da.“ Dann sehen wir ihn auf der Karte. Er ist geografisch sehr überzeugt von sich.]=])
Set("NERGLISH_AZEROTH_22", [=[Der Tank sagt „Hinten rum is kürzer.“ Nach sieben Gruppen fragt der Heiler „Kürzer als was?“ Der Tank sagt „Als wenn ma jetzt umdrehen.“]=])
Set("NERGLISH_AZEROTH_23", [=[Der Magier macht aus einem Gegner ein Schaf. Der Krieger haut’s. „Warum?“ „Es hat mi so ang’schaut, wie nur ein Schaf schauen kann, das genau weiß, was es getan hat.“]=])
Set("NERGLISH_AZEROTH_24", [=[Im Dungeon fragt mich wer, ob die Patrouille gefährlich is. I sag „Nur wenn’s di sieht.“ Er winkt ihr. „Na gut. Jetzt is sie gefährlich und kennt di.“]=])
Set("NERGLISH_AZEROTH_25", [=[Unser Heiler sagt „I brauch Mana.“ Der Tank fragt „Wie viel?“ „Für dich? I würd beim Brunnen anfangen.“]=])
Set("NERGLISH_AZEROTH_26", [=[Beim ersten Boss steht der Schurke heimlich hinter ihm. Der Boss dreht sich um. Der Schurke sagt „Grüß Gott. I komm wegen der Hintertür.“]=])
Set("NERGLISH_AZEROTH_27", [=[Der Händler vorm Dungeon fragt, warum ich schon wieder hier bin. „Verkaufen.“ Er schaut auf meine kaputte Rüstung. „Mutig, dass S’ überhaupt noch in der Kategorie denken.“]=])
Set("NERGLISH_AZEROTH_28", [=[Der Zwerg sagt „Links bei der Ecke bitte eng gehen.“ Unser Tauren probiert’s. „Geht’s ohne Schulterpanzer?“ „Ja.“ „Gut, dann werf i ihn rüber und komm nach.“]=])
Set("NERGLISH_AZEROTH_29", [=[Wir haben eine Truhe gefunden und fünf Minuten überlegt, wem sie gehört. Dann kam die Patrouille zurück. Die war sich sofort einig.]=])
Set("NERGLISH_AZEROTH_30", [=[Im Dungeon hat der Heiler gefragt, ob der Tank in Deckung gehen kann. „Freilich.“ Dann hat er sich hinterm Heiler versteckt. Geholfen hat’s genau einem von uns.]=])
Set("NERGLISH_AZEROTH_31", [=[Der Boss hat einen Schlüssel fallen lassen. Der Schurke steckt ihn ein. „Wos brauchst den?“ „Für den Fall, dass i irgendwann erwachsen werd und Türen normal aufmach.“]=])
Set("NERGLISH_AZEROTH_32", [=[Unser Priester hat sich am Eingang verlaufen. Beim Endboss sagt er „I kenn jetzt den Rückweg.“ Der Tank sagt „Endlich einer, der positiv denkt.“]=])
Set("NERGLISH_AZEROTH_33", [=[Der Tank hat „linke Seite frei“ gesagt. Der Jäger hat verstanden, dass er sich dort was zum Pull aussuchen darf. Die linke Seite war sehr bald wieder voll.]=])
Set("NERGLISH_AZEROTH_34", [=[Beim Dungeon-Loot fragt wer „Kann das wer brauchen?“ Unser Magier sagt „I bin Schneider, gib her.“ Es war ein Streitkolben. „Na geh, als Nähgewicht halt.“]=])
Set("NERGLISH_AZEROTH_35", [=[Der letzte Gegner rennt weg. Wir rennen hinterher. Nach der dritten Kurve fragt der Tank „Sagt’s amal, macht der grad eine Führung mit uns?“]=])
Set("NERGLISH_AZEROTH_36", [=[Ein Gegner heilt sich selber. Unser Heiler schaut neidisch. „Schau, der fragt wenigstens vorher ned, ob er in der Heilung stehen muss.“]=])
Set("NERGLISH_AZEROTH_37", [=[Der erste Boss hat unseren Tank weggeschleudert. Er steht auf, klopft sich ab und sagt „Passt. Von da seh i, wer bei uns ganz hinten nix tut.“]=])
Set("NERGLISH_AZEROTH_38", [=[Unser Schamane stellt vorm Pull ein Totem auf. Der Tank wartet. „Kurze Gedenkminute?“ „Na, i wollt nur markieren, wo du nachher wieder aufstehst.“]=])
Set("NERGLISH_AZEROTH_39", [=[Kurz vor Schluss fragt unser Krieger „War da irgendwo a Nebenraum?“ Der Rest der Gruppe antwortet sehr schnell und sehr geschlossen „Na.“]=])
Set("NERGLISH_AZEROTH_40", [=[Nach dem Dungeon sagt der Heiler „War eh gemütlich.“ Dann schaut er auf die Uhr. „Ah. I hab unterm Tisch die ganze Zeit auf die Bremse getreten.“]=])
Set("NERGLISH_AZEROTH_41", [=[In Westfall soll ich fünf Säcke Getreide holen. Der Bauer steht die ganze Zeit neben dem ersten Sack. I bring ihm die anderen vier. „Den da schafft ma z’samm.“]=])
Set("NERGLISH_AZEROTH_42", [=[Ich hab in Durotar einen Eber gezähmt. Jetzt weiß ich, dass er persönlich wird, wenn man beim Händler „Alles verkaufen“ sagt und ihn dabei anschaut.]=])
Set("NERGLISH_AZEROTH_43", [=[Der Questgeber sagt „Ihr seid unsere letzte Hoffnung.“ Gleich hinter mir steht wer in derselben Questschlange. Anscheinend hat die Hoffnung einen Nachmittagsschalter.]=])
Set("NERGLISH_AZEROTH_44", [=[Beim Kräutersammeln in Elwynn war einer immer vor mir. I hab ihn gefragt, wie er so schnell is. „I such kane Kräuter. I folg nur dir, weil du so schön langsam nach ihnen schaust.“]=])
Set("NERGLISH_AZEROTH_45", [=[In den Sümpfen soll ich jemanden eskortieren. Der bleibt unterwegs bei jeder Gefahr stehen und schaut sie an. Begleiten hab ich versprochen. Erziehen war offenbar im Kleingedruckten.]=])
Set("NERGLISH_AZEROTH_46", [=[Beim Angeln in Loch Modan hat’s an der Leine gezogen. I zieh zurück. Vom anderen Ufer brüllt einer „Lass mei Angel los!“ Endlich wer, der auch nix fangt.]=])
Set("NERGLISH_AZEROTH_47", [=[Ich hab in Tanaris ein Erzvorkommen entdeckt. Bis ich vom Reittier unten war, war’s weg. Der andere Bergbauer hat noch freundlich gewunken. Mit meiner Hand wär ich auch gern so schnell gewesen.]=])
Set("NERGLISH_AZEROTH_48", [=[In Dun Morogh hab ich meinen Ruhestein daheim vergessen wollen. Dann is ma eingefallen, dass ich mit dem Ruhestein überhaupt erst heimkomm. Seitdem pack i beim Verreisen a bissl aufmerksamer.]=])
Set("NERGLISH_AZEROTH_49", [=[Ein Auftrag schickt mich in die nächste Siedlung, um einen Brief zu überbringen. Dort bekomm ich einen Brief für denselben Auftraggeber. I glaub, die zwei hätt’n einander noch viel zu sagen, wenn’s a Fenster aufmachen.]=])
Set("NERGLISH_AZEROTH_50", [=[Ich hab beim Sammeln in Stranglethorn so oft auf die Karte g’schaut, dass mich ein Tiger erwischt hat. Er hat ohne Karte direkt herg’funden.]=])
Set("NERGLISH_AZEROTH_51", [=[Am Wegekreuz wollt ich gemütlich die Aussicht genießen. Nach zwei Minuten hat mich ein Questgeber angesprochen. „Wennst eh schon so aufmerksam herumstehst …“]=])
Set("NERGLISH_AZEROTH_52", [=[In Teldrassil hab ich auf einen seltenen Gegner gewartet. Wie er endlich auftaucht, sind wir zu sechst. I glaub, für ihn waren wir der seltene Gegner.]=])
Set("NERGLISH_AZEROTH_53", [=[Mein Reittier hat sich am Zaun verhakt. Ein Gnom reitet unten durch. Er schaut hinauf und sagt „Von da unten hat’s leicht ausg’schaut.“]=])
Set("NERGLISH_AZEROTH_54", [=[„Bring mir acht Zähne“, sagt der Questgeber. I komm nach zehn Tieren mit drei zurück. „Die Gegend könnt an Zahnarzt brauchen. Einen Helden hat’s jetzt eh.“]=])
Set("NERGLISH_AZEROTH_55", [=[In den Pestländern fragt mich wer, ob ich kurz beim Kämpfen helfen kann. „Glei fertig“, sagt er. Dann erschein ich in seiner Einladungsnachricht als Tagesordnungspunkt zwei.]=])
Set("NERGLISH_AZEROTH_56", [=[Ich hab drei Quests gleichzeitig verfolgt. Dann waren überall Pfeile auf der Karte. Jetzt hätt ich gern eine vierte Quest, die mir erklärt, wo ich anfangen soll.]=])
Set("NERGLISH_AZEROTH_57", [=[Beim Wildhäuten in Mulgore sagt mein Begleiter „Kann i helfen?“ „Haltest das Fell?“ Er streichelt’s. „Helfen“, hab i g’sagt. „Verabschieden kann i mi selber.“]=])
Set("NERGLISH_AZEROTH_58", [=[In der Brachlandsonne fragt ein Untoter, ob er rot wird. Sein Freund sagt „Schwer zu sagen. Dreh di amal auf die Seite, die noch Haut hat.“]=])
Set("NERGLISH_AZEROTH_59", [=[Beim Questen spawnt der Gegner genau hinter mir wieder. „Du schon wieder?“ sag ich. Er schaut genauso entsetzt. Da hab i ihm zum ersten Mal einen schönen Tag g’wünscht.]=])
Set("NERGLISH_AZEROTH_60", [=[Ich bin in Azeroth losgeritten, um schnell eine Quest abzugeben. Eine Stunde später hatte ich acht Kräuter, drei neue Quests und einen Fisch. Der Questgeber freut sich sicher, wenn ich ihm davon erzähl.]=])
Set("NERGLISH_AZEROTH_61", [=[In Goldhain frag ich den Wirt, ob mein Wolf mit rein darf. „Wenn er stubenrein is.“ Der Wolf schaut auf den Zwerg unterm Tisch. „Ja“, sag i. „Für den da kann i aber nix versprechen.“]=])
Set("NERGLISH_AZEROTH_62", [=[Ein Troll bestellt „A bissl was Scharfes.“ Der Wirt stellt Senf auf den Tisch. Der Troll kostet und sagt „Gut. Jetzt kannst die Portion für die Erwachsenen bringen.“]=])
Set("NERGLISH_AZEROTH_63", [=[Im Gasthaus hab ich nach einem ruhigen Zimmer gefragt. Der Wirt sagt „Oben links. Wenn’s unten laut wird, machens die Tür zu.“ „Vom Zimmer?“ „Vom Gasthaus. Dann gehen die Leut heim.“]=])
Set("NERGLISH_AZEROTH_64", [=[Der Goblin bestellt ein Bier auf Anschreiben. Der Wirt dreht die Kreidetafel um. „Deine Seite is voll.“]=])
Set("NERGLISH_AZEROTH_65", [=[Ein Ork fragt, was heut auf der Karte steht. „Gulasch.“ „Und gestern?“ „Gestern hat’s noch a bissl Abwechslung g’habt. Da war mehr Brot dabei.“]=])
Set("NERGLISH_AZEROTH_66", [=[Unser Magier hat beim Wirt Eis für sein Getränk bestellt. „Kannst selber machen“, sagt der Wirt. Der Magier dreht die Hand. Drei Tische kriegen Winter. „I hab Würferl g’meint.“]=])
Set("NERGLISH_AZEROTH_67", [=[Der Zwerg hat seine Axt neben die Garderobe gestellt. Wie er heimgeht, hängt ein fremder Mantel drauf. „Den hab i eh gebraucht“, sagt er und nimmt beides mit.]=])
Set("NERGLISH_AZEROTH_68", [=[Im Gasthaus hat ein Koch mit Fertigkeit eins gefragt, ob wer kosten will. Der Untote hebt die Hand. „Bei mir is der schlimmste Ausgang scho eingetreten.“]=])
Set("NERGLISH_AZEROTH_69", [=[Der Wirt fragt den Paladin, ob er vor dem Essen beten möchte. „Kommt drauf an“, sagt der. „War des beim letzten Gast notwendig?“]=])
Set("NERGLISH_AZEROTH_70", [=[Ein Tauren setzt sich auf einen kleinen Hocker. Es kracht. Der Wirt schaut herüber. „Gemütlicher so, gell? Jetzt bist auf deiner Sitzhöhe.“]=])
Set("NERGLISH_AZEROTH_71", [=[Im Gasthaus spielt einer Laute. Ich frag, ob er auch was Leiseres kann. Er nickt und stimmt sie zehn Minuten lang. War tatsächlich sein bestes Stück.]=])
Set("NERGLISH_AZEROTH_72", [=[Ein Druide fragt, ob’s fürs Frühstück Honig gibt. „Für zwei Kupfer extra“, sagt die Wirtin. Der Druide wird zum Bären. „Ah. Für dich zum Mitnehmen.“]=])
Set("NERGLISH_AZEROTH_73", [=[Der Wirt in Beutebucht sagt, bei ihm wird frisch gekocht. Aus der Küche brüllt wer „Er wehrt sich noch!“ I glaub, frischer geht’s nimmer.]=])
Set("NERGLISH_AZEROTH_74", [=[Mein Jäger sagt, sein Pet kriegt vom Tisch nix. Der Wirt serviert. Das Pet sitzt unter meinem Sessel und schaut, als hätt’s mich auf die Idee mit dem Schnitzel gebracht.]=])
Set("NERGLISH_AZEROTH_75", [=[Ein Gnom bittet um a kleines Glas. Der Wirt bringt ihm einen Fingerhut. Der Gnom hebt ihn auf Augenhöhe. „Schön. Und daraus schenkst ma jetzt ein.“]=])
Set("NERGLISH_AZEROTH_76", [=[Beim Essen fragt wer, wie zart das Fleisch is. Der Wirt drückt mir ein schärferes Messer in die Hand. „Jetzt probierns die Antwort selber.“]=])
Set("NERGLISH_AZEROTH_77", [=[Ein Geist bestellt im Gasthaus ein Bier. Der Wirt stellt’s hin und legt einen Bierdeckel drunter. „I kenn di. Bei dir geht alles durch.“]=])
Set("NERGLISH_AZEROTH_78", [=[Der Priester fragt beim Wirt nach der Tagessuppe. „Bohnensuppe.“ Er nickt. „Dann setz ma uns ans Fenster. I kann heut nur einzeln reinigen.“]=])
Set("NERGLISH_AZEROTH_79", [=[In Eisenschmiede hat wer beim Wirt „a Runde für alle“ gerufen. Der Wirt sperrt die Tür auf. „Soll i die von draußen auch reinlassen, bevor’s es euch anders überlegt’s?“]=])
Set("NERGLISH_AZEROTH_80", [=[In Goldhain fragt die Wirtin, ob ich gut g’schlafen hab. „Na. In der Früh hat mein Zimmer auf einmal nach Fisch g’rochen.“ Sie schaut nach oben. „Ah, da Angler is wieder über Ihnen.“]=])
Set("NERGLISH_AZEROTH_81", [=[Bei der Bank in Sturmwind fragt mich der Schalterbeamte, ob ich wertvolle Gegenstände einlagern will. „Drei graue Hosen.“ Er hebt eine Augenbraue. „Emotional wertvoll.“]=])
Set("NERGLISH_AZEROTH_82", [=[Der Auktionator fragt, ob ich einen Sofortkaufpreis setzen will. „Ja, wie beim letzten Mal.“ Er schaut nach. „Der war so hoch, dass nur Ihre Mutter draufg’schaut hat. Und die hat Sie angerufen.“]=])
Set("NERGLISH_AZEROTH_83", [=[In Orgrimmar wollt ich einen Brief an „Thrall“ schicken. Die Post sagt „Adresse unvollständig.“ I schreib „Thrall, der Große“. „Geht doch.“]=])
Set("NERGLISH_AZEROTH_84", [=[Der Schmied fragt, ob ich meinen Helm enger haben will. „Ja, er rutscht beim Kämpfen.“ Er haut einmal drauf. „Jetzt rutscht er nur mehr beim Denken.“]=])
Set("NERGLISH_AZEROTH_85", [=[Der Barbier fragt meinen Zwerg, wie viel vom Bart weg soll. „Alles, was beim Essen stört.“ Er schaut auf das Brot, das schon drin hängt. „Brot behalten S’?“]=])
Set("NERGLISH_AZEROTH_86", [=[In Sturmwind fragt ein Tourist die Wache, wo die Altstadt is. „Da drüben.“ „Und die Neustadt?“ „Wenn’s fertig is, sag i’s Ihnen.“]=])
Set("NERGLISH_AZEROTH_87", [=[Beim Kriegerlehrer lern ich eine neue Fähigkeit. „Macht sechs Gold.“ I will feilschen. „Des lernens beim Schurkenlehrer. Macht bei mir jetzt sieben.“]=])
Set("NERGLISH_AZEROTH_88", [=[Ein Gnom verkauft in Eisenschmiede einen „selbstlaufenden Werkzeugkasten“. I frag, was ihn antreibt. Von drinnen sagt wer „Glaub ihm koa Wort.“]=])
Set("NERGLISH_AZEROTH_89", [=[Ich hab beim Auktionator nach einem günstigen Umhang gefragt. „Sie könnten selber einen nähen.“ „I kann ned nähen.“ „Na eben, drum tät i Ihnen den teuersten zutrauen.“]=])
Set("NERGLISH_AZEROTH_90", [=[In Orgrimmar fragt wer im Handelschat nach einer ruhigen Gilde. Zwölf Leute schreiben gleichzeitig „WIR!!!“ I glaub, er sucht noch.]=])
Set("NERGLISH_AZEROTH_91", [=[Bei den Kanälen von Sturmwind fragt mich einer, ob man hier schwimmen darf. „Na, aber hinfallen passiert laufend.“]=])
Set("NERGLISH_AZEROTH_92", [=[Unser Tauren fragt am Stadttor, warum er den Helm abnehmen muss. Die Wache misst kurz mit der Hand nach. „Weil der Torbogen älter is als Ihr Helm und i nur einen von beiden ersetzen kann.“]=])
Set("NERGLISH_AZEROTH_93", [=[Der Händler in Sturmwind fragt meinen Schurken, ob er bar bezahlt. „Ja.“ Er schaut in seine Lade. „Mit Ihrem Geld wär mir halt lieber.“]=])
Set("NERGLISH_AZEROTH_94", [=[Ein Schneider in Darnassus hat meine Robe umgenäht. „Jetzt sitzt sie perfekt.“ I setz mich. Er zückt schon wieder die Schere. „Ah. Sitzen wollten S’ auch.“]=])
Set("NERGLISH_AZEROTH_95", [=[Der Alchemist fragt, ob ich einen Trank gegen Müdigkeit will. „Heut nimmer.“ Er nickt. „Kommen S’ morgen ausgeschlafen, dann erklär i Ihnen die Dosierung.“]=])
Set("NERGLISH_AZEROTH_96", [=[In Eisenschmiede hab ich einen Gnom um Hilfe bei der Reparatur gefragt. „Kostet nix“, sagt er. „Die Reparatur is kostenlos. Die Teile neben uns waren vorher so ned eingeplant.“]=])
Set("NERGLISH_AZEROTH_97", [=[Bei der Post in Orgrimmar kommt ein Paket zurück. „Empfänger nicht auffindbar.“ Es war an meinen Zweitcharakter. I hab kurz überlegt, ob ich ihm schreiben soll.]=])
Set("NERGLISH_AZEROTH_98", [=[Beim Rüstungshändler sag ich „Ich hätt gern was, das Eindruck macht.“ Er zeigt mir den Preis. „So viel Eindruck hab i gar ned g’meint.“]=])
Set("NERGLISH_AZEROTH_99", [=[Eine Wache in Sturmwind hat meinen Hexer gefragt, ob sein Dämon angemeldet is. „Des is a Begleiter.“ „Dann soll er aufhören, Auskunft zu geben. Die Leut glauben ihm schon mehr als mir.“]=])
Set("NERGLISH_AZEROTH_100", [=[Am Stadttor fragt die Wache den Murloc nach seinem Beruf. „Mrrgrl.“ „Handel?“ Der Murloc schüttelt den Kopf. „Verwaltung?“ Da nickt er. Den Rest klären sie schriftlich.]=])
